// Créer : nom, valeur, expiration (timestamp)
setcookie("langue", "fr", time() + 30 * 24 * 3600);

// Lire (à la requête suivante)
echo $_COOKIE["langue"] ?? "fr";

// Supprimer : date passée
setcookie("langue", "", time() - 3600);

session_start();          // toujours en premier

$_SESSION["user"] = "Amal";
echo $_SESSION["user"];

// Déconnexion
session_unset();
session_destroy();
